import os
from flask import request, send_file, abort

SAFE_DIR = '/var/app/uploads'

@app.route('/download')
def download_file():
    filename = request.args.get('file')
    if not filename:
        abort(400)
    full_path = os.path.join(SAFE_DIR, filename)
    # TOCTOU: check happens before use
    if not os.path.exists(full_path):
        abort(404)
    if not os.path.realpath(full_path).startswith(SAFE_DIR):
        abort(403)
    # Race window here — attacker can replace file with symlink between check and open
    return send_file(full_path)

