import org.springframework.web.bind.annotation.*;
import com.fasterxml.jackson.databind.ObjectMapper;

@RestController
public class UserController {
    @PostMapping("/api/users/update")
    public ResponseEntity<?> updateUser(
            @RequestBody Map<String, Object> updates,
            @AuthenticationPrincipal UserDetails principal) {
        User user = userRepository.findByUsername(principal.getUsername());
        ObjectMapper mapper = new ObjectMapper();
        // Merge all fields from request into user object
        User updated = mapper.convertValue(updates, User.class);
        updated.setId(user.getId());  // Preserve ID
        userRepository.save(updated);
        return ResponseEntity.ok(updated);
    }
}

import xml.etree.ElementTree as ET
from flask import request, jsonify

@app.route('/api/parse-config', methods=['POST'])
def parse_config():
    xml_data = request.data
    try:
        root = ET.fromstring(xml_data)
        config = {}
        for child in root:
            config[child.tag] = child.text
        return jsonify(config)
    except ET.ParseError as e:
        return jsonify({'error': str(e)}), 400

import org.w3c.dom.*;
import javax.xml.parsers.*;
import java.io.*;

@WebServlet("/parse")
public class XmlParserServlet extends HttpServlet {
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws IOException, ServletException {
        String xmlInput = req.getParameter("data");
        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            // Missing: factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
            DocumentBuilder builder = factory.newDocumentBuilder();
            Document doc = builder.parse(new InputSource(new StringReader(xmlInput)));
            NodeList nodes = doc.getElementsByTagName("name");
            resp.getWriter().write(nodes.item(0).getTextContent());
        } catch (Exception e) {
            resp.sendError(500, e.getMessage());
        }
    }
}

