import requests
from urllib.parse import urlparse
from flask import request, jsonify

@app.route('/fetch')
def fetch_url():
    url = request.args.get('url', '')
    parsed = urlparse(url)
    # Only check scheme — IP/hostname not validated
    if parsed.scheme not in ('http', 'https'):
        return jsonify({'error': 'Only HTTP/HTTPS allowed'}), 400
    try:
        resp = requests.get(url, timeout=5, allow_redirects=True)
        return jsonify({'content': resp.text[:1000], 'status': resp.status_code})
    except requests.RequestException as e:
        return jsonify({'error': str(e)}), 500

from flask import request, jsonify, abort
import sqlite3

ALLOWED_SORT_FIELDS = {'name', 'email', 'created_at', 'last_login'}
ALLOWED_ORDERS = {'ASC', 'DESC'}

@app.route('/api/users')
def list_users():
    sort_field = request.args.get('sort', 'name')
    sort_order = request.args.get('order', 'ASC').upper()
    if sort_field not in ALLOWED_SORT_FIELDS:
        abort(400)
    if sort_order not in ALLOWED_ORDERS:
        abort(400)
    conn = sqlite3.connect('users.db')
    cursor = conn.cursor()
    # Both dynamic parts validated against whitelists
    query = f"SELECT id, name, email FROM users ORDER BY {sort_field} {sort_order}"
    cursor.execute(query)
    rows = cursor.fetchall()
    conn.close()
    return jsonify(rows)

from jinja2 import Environment, select_autoescape, FileSystemLoader
from flask import request, render_template_string

env = Environment(
    loader=FileSystemLoader('templates'),
    autoescape=select_autoescape(['html', 'xml', 'htm'])
)

@app.route('/greet')
def greet():
    name = request.args.get('name', 'Guest')
    # Safe: user input passed as a VARIABLE, not embedded in template source
    template = env.from_string("<h1>Hello {{ name }}!</h1><p>Welcome.</p>")
